css:
.st { overflow: hidden; padding-block: var(--os-space-xs); }
.st__track { display: flex; width: max-content; will-change: transform; animation: stmarq 60s linear infinite; }
.st--js .st__track { animation: none; }
.st__list { display: flex; flex: none; align-items: center; margin: 0; padding: 0; list-style: none; }
.st__item {
  display: flex;
  align-items: center;
  gap: var(--os-space-lg);
  padding-right: var(--os-space-lg);
  font-family: var(--os-font-heading);
  font-weight: var(--os-font-weight-heading);
  font-size: var(--os-type-h2-font-size);
  line-height: 1.15;
  white-space: nowrap;
  color: var(--os-color-heading);
}
.st__star { flex: none; width: 0.6em; height: 0.6em; fill: var(--os-color-ochre); }
@keyframes stmarq { to { transform: translate3d(-33.3333%, 0, 0); } }
@media (prefers-reduced-motion: reduce) { .st__track { animation: none; } }

js:
const st = root.querySelector('.st');
const track = root.querySelector('[data-st-track]');
if (!st || !track || ctx.reducedMotion) return;
st.classList.add('st--js');
let third = 0;
let x = 0;
let dir = 1;
let last = 0;
let lastY = window.scrollY;
let visible = false;
let raf = 0;
const measure = () => { third = track.scrollWidth / 3; };
measure();
new ResizeObserver(measure).observe(track);
const tick = (t) => {
  raf = 0;
  if (!visible) return;
  const dt = last ? Math.min(64, t - last) : 16;
  last = t;
  const y = window.scrollY;
  const dy = y - lastY;
  lastY = y;
  if (dy > 0) dir = 1;
  else if (dy < 0) dir = -1;
  x += dir * (dt * 0.03 + Math.abs(dy) * 0.5);
  if (third > 0) x = ((x % third) + third) % third;
  track.style.transform = 'translate3d(' + (-x) + 'px, 0, 0)';
  raf = requestAnimationFrame(tick);
};
new IntersectionObserver((entries) => {
  visible = entries[0].isIntersecting;
  if (visible && !raf) {
    last = 0;
    lastY = window.scrollY;
    raf = requestAnimationFrame(tick);
  }
}).observe(st);
